  private async spawnHeadlessJob(
    id: string,
    prompt: string,
    runtime: RuntimePaths,
    returnToSessionId?: string,
    returnMailboxPath?: string,
  ): Promise<LaunchResult> {
    const { spawn } = await import("child_process");
    const schedulerCwd = runtime.workspaceRoot;
    const cliPath = runtime.cliPath;

    // Determine output log file
    const logDir = path.join(schedulerCwd, ".lowcal", "launch-tasks");
    await fs.mkdir(logDir, { recursive: true });
    const logFile = path.join(logDir, `${id}.json`);

    const env: NodeJS.ProcessEnv = {
      ...process.env,
      LOWCAL_HEADLESS: "1",
      LOWCAL_JOB_ID: id,
      LOWCAL_HEADLESS_PRETTY: "1",
      [ENV_DISABLE_LAUNCH_TASK]: "1",
    };
    if (returnToSessionId && returnMailboxPath) {
      env[ENV_RETURN_TO_SESSION_ID] = returnToSessionId;
      env[ENV_RETURN_MAILBOX_PATH] = returnMailboxPath;
      env[ENV_RETURN_FROM_TASK_ID] = id;
    }

    const args = [
      cliPath,
      "--prompt",
      prompt,
      "--job-id",
      id,
      "--output",
      logFile,
    ];

    return await new Promise<LaunchResult>((resolve, reject) => {
      const child = spawn(process.execPath, args, {
        stdio: "ignore",
        env,
        cwd: schedulerCwd,
        detached: true, // Detach from parent process
      });
      let settled = false;

      child.on("error", (error) => {
        if (settled) return;
        settled = true;
        reject(error);
      });

      child.on("spawn", () => {
        if (settled) return;
        settled = true;
        child.unref();
        resolve({
          requestedMode: "headless",
          actualMode: "headless",
          logPath: logFile,
          pid: child.pid ?? undefined,
          returnMailboxPath,
          returnToSessionId,
        });
      });

      child.on("exit", (code, signal) => {
        if (settled) return;
        settled = true;
        if (code !== 0) {
          reject(new Error(`Process exited with code ${code}`));
        } else {
          reject(
            new Error(
              `Process exited before launch was acknowledged (signal: ${
                signal ?? "none"
              }).`,
            ),
          );
        }
      });
    });
  }

